icon-action:
import { useState } from 'react';
import { DsIconButton } from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';
export function Example() {
  const [refreshes, setRefreshes] = useState(0);
  return <div style={{display:'flex', alignItems:'center', flexWrap:'wrap', gap:16, paddingBottom:64}}>
    <DsIconButton icon="refresh" label="Обновить объекты" onClick={()=>setRefreshes(value=>value+1)}/>
    <p role="status">Обновлений: {refreshes}</p>
  </div>;
}

preferred-placement:
import { useState } from 'react';
import { DsButton, DsTooltip } from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';
export function Example() {
  const [help,setHelp] = useState(false);
  return <div style={{display:'flex', flexWrap:'wrap', alignItems:'center', gap:16, justifyContent:'flex-end', paddingTop:48, paddingBottom:64}}>
    <DsTooltip placement="top" content="Показать памятку по работе с клавиатурой"><DsButton tone="secondary" onClick={()=>setHelp(value=>!value)} aria-expanded={help}>Сочетания клавиш</DsButton></DsTooltip>
    {help?<p>Tab — следующее действие, Shift+Tab — предыдущее, Escape — закрыть подсказку.</p>:null}
  </div>;
}

