import { useState } from 'react';
import { DsButton, DsTooltip } from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';
export function Example() {
  const [saved, setSaved] = useState(false);
  return <div style={{display:'flex', alignItems:'center', flexWrap:'wrap', gap:16, paddingBottom:64}}>
    <DsTooltip content="Сохранить текущий набор столбцов для следующих сеансов"><DsButton tone="secondary" onClick={()=>setSaved(true)}>Запомнить вид</DsButton></DsTooltip>
    <p role="status">{saved?'Вид сохранён.':'Вид ещё не сохранён.'}</p>
  </div>;
}
